def format_date(dt: datetime) -> str:
    """주어진 datetime 객체를 한국식 날짜 포맷으로 변환합니다."""
    day_of_week = ['일', '월', '화', '수', '목', '금', '토']
    formatted_date = dt.strftime(f"%Y-%m-%d ({day_of_week[dt.weekday()]}) %p %I:%M")
    return formatted_date

